def tr(d): return {'R':'D','D':'L','L':'U','U':'R'}[d]
def tl(d): return {'R':'U','U':'L','L':'D','D':'R'}[d]
def stra(d): return d

def try_snake(order,lengths,firstdir,turnfn,mode='overwrite',conn=1):
    grid=[[0]*7 for _ in range(7)]; grid[0][3]=5
    d=firstdir; r,c=1,3; ok=True
    for sh in order:
        dy,dx=DIRS[d]
        for k in range(lengths[sh]):
            rr,cc=r+dy*k,c+dx*k
            if not(0<=rr<7 and 0<=cc<7): return None,False
            v=grid[rr][cc]
            if mode=='xor' and v not in (0,5): grid[rr][cc]=0
            else: grid[rr][cc]=COL[sh]
        r,c=r+dy*(lengths[sh]-1),c+dx*(lengths[sh]-1)
        d=turnfn(d); dy,dx=DIRS[d]; r,c=r+conn*dy,c+conn*dx
        if not(0<=r<7 and 0<=c<7): return None,False
    return grid,ok

